hpy-007.text:
The LFU cache will use a combination of hash maps and doubly linked lists to achieve O(1) operations. A `key_to_node` map stores each key’s node, a `freq_to_dll` map stores a doubly linked list for each frequency level, and a `min_freq` variable tracks the current minimum frequency. Each node contains the key, value, frequency, and pointers for the doubly linked list. On `get` or `put`, the node’s frequency is incremented, it is moved to the next frequency list, and `min_freq` is updated when the current minimum list becomes empty. When evicting, the least‑recently‑used node from the `min_freq` list is removed. Edge cases include capacity 0 (no operations allowed) and ties where the LRU node is evicted.

```python
class LFUCache:
    class Node:
        __slots__ = ('key', 'value', 'freq', 'prev', 'next')
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.freq = 1
            self.prev = None
            self.next = None

    class DLL:
        __slots__ = ('head', 'tail')
        def __init__(self):
            self.head = self.Node(0, 0)
            self.tail = self.Node(0, 0)
            self.head.next = self.tail
            self.tail.prev = self.head
        def add_to_head(self, node):
            node.prev = self.head
            node.next = self.head.next
            self.head.next.prev = node
            self.head.next = node
        def remove(self, node):
            node.prev.next = node.next
            node.next.prev = node.prev
        def pop_tail(self):
            node = self.tail.prev
            self.remove(node)
            return node

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.key_to_node = {}
        self.freq_to_dll = {}

    def _get_dll(self, freq):
        if freq not in self.freq_to_dll:
            self.freq_to_dll[freq] = self.DLL()
        return self.freq_to_dll[freq]

    def get(self, key: int) -> int:
        if self.capacity == 0:
            return -1
        if key not in self.key_to_node:
            return -1
        node = self.key_to_node[key]
        self._update_node(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_to_node:
            node = self.key_to_node[key]
            node.value = value
            self._update_node(node)
        else:
            if self.size == self.capacity:
                self._evict()
            node = self.Node(key, value)
            self.key_to_node[key] = node
            self._get_dll(1).add_to_head(node)
            self.min_freq = 1
            self.size += 1

    def _update_node(self, node):
        freq = node.freq
        dll = self.freq_to_dll[freq]
        dll.remove(node)
        if freq == self.min_freq and dll.head.next == dll.tail:
            self.min_freq += 1
        node.freq += 1
        self._get_dll(node.freq).add_to_head(node)

    def _evict(self):
        dll = self.freq_to_dll[self.min_freq]
        node = dll.pop_tail()
        del self.key_to_node[node.key]
        self.size -= 1
```

