hpy-012.text:
The solution parses each cron field into a list of allowed values, handling `*`, ranges, step values, and comma‑separated lists. For the day‑of‑month and day‑of‑week fields we apply the “OR” rule when both are restricted and the “AND” rule when only one is restricted. A search proceeds minute‑by‑minute, checking each field against the current time, and returns the first datetime that satisfies all constraints with seconds and microseconds set to zero. Edge cases include empty lists (invalid expression), out‑of‑range values, and step values that produce no matches.

```python
import re
from datetime import datetime, timedelta

def _parse_field(field, min_val, max_val):
    if field == '*':
        return list(range(min_val, max_val + 1))
    values = set()
    for part in field.split(','):
        if '/' in part:
            base, step_str = part.split('/')
            step = int(step_str)
            if step <= 0:
                raise ValueError(f"Invalid step {step_str}")
            if base == '*':
                values.update(range(min_val, max_val + 1, step))
            else:
                if '-' in base:
                    start, end = map(int, base.split('-'))
                    if start > end:
                        raise ValueError(f"Invalid range {base}")
                    values.update(range(start, end + 1, step))
                else:
                    val = int(base)
                    if val < min_val or val > max_val:
                        raise ValueError(f"Value {val} out of range")
                    values.add(val)
        elif '-' in part:
            start, end = map(int, part.split('-'))
            if start > end:
                raise ValueError(f"Invalid range {part}")
            values.update(range(start, end + 1))
        else:
            val = int(part)
            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of range")
            values.add(val)
    if not values:
        raise ValueError(f"No values for field {field}")
    return sorted(values)

def next_fire(expr, after):
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have 5 fields")
    minute_vals = _parse_field(parts[0], 0, 59)
    hour_vals   = _parse_field(parts[1], 0, 23)
    day_vals    = _parse_field(parts[2], 1, 31)
    month_vals  = _parse_field(parts[3], 1, 12)
    dow_vals    = _parse_field(parts[4], 0, 6)

    cur = after + timedelta(seconds=1)
    cur = cur.replace(second=0, microsecond=0)

    while True:
        if cur.month not in month_vals:
            cur = (cur.replace(day=1, hour=0, minute=0) + timedelta(days=32)).replace(day=1)
            continue
        if cur.day not in day_vals and cur.weekday() not in dow_vals:
            cur = cur.replace(hour=0, minute=0) + timedelta(days=1)
            continue
        if cur.hour not in hour_vals:
