            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
        elif expr[i] in '+-*/%()':
            tokens.append(expr[i])
            i += 1
        elif expr[i] == '**':
            tokens.append('**')
            i += 2
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

