```python
class WildcardTrie:
    def __init__(self):
        self.root = {}

    def add(self, word):
        if not word:
            return False
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['_count'] = node.get('_count', 0) + 1
        return True

    def remove(self, word):
        if not word:
            return False
        node = self.root
        for ch in word:
            if ch not in node:
                return False
            node = node[ch]
        if node.get('_count', 0) == 0:
            return False
        node['_count'] -= 1
        return True

    def search(self, pattern):
        results = []

        def dfs(idx, node, path):
            if idx == len(pattern):
                if node.get('_count', 0) > 0:
                    results.append(''.join(path))
                return
            ch = pattern[idx]
            if ch == '.':
                for key, child in node.items():
                    if key == '_count':
                        continue
                    path.append(key)
                    dfs(idx + 1, child, path)
                    path.pop()
            else:
                if ch in node:
                    path.append(ch)
                    dfs(idx + 1, node[ch], path)
                    path.pop()

        dfs(0, self.root, [])
        return sorted(results)
```

