The `RollbackDSU` maintains a stack of changes (parent updates and size modifications) so that each `union` can be undone by popping the stack. A snapshot records the current stack size, allowing `rollback` to revert to that state. Path compression is omitted because it would break the ability to undo changes.

```python
class RollbackDSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.stack = []          # each entry: (child, old_parent, root, old_size)
        self.comp_cnt = n

    def find(self, x: int) -> int:
        # No path compression – just follow parent links
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False

        # Union by size: attach smaller tree under larger one
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra

        # Record changes for possible rollback
        self.stack.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.comp_cnt -= 1
        return True

    def snapshot(self):
        # Opaque token is just the current stack length
        return len(self.stack)

    def rollback(self, token):
        while len(self.stack) > token:
            child, old_parent, root, old_size = self.stack.pop()
            self.parent[child] = old_parent
            self.size[root] = old_size
            self.comp_cnt += 1

    def components(self) -> int:
        return self.comp_cnt
