def subtract(base, cuts):
    # Helper to merge overlapping/adjacent intervals
    def merge(intervals):
        if not intervals:
            return []
        intervals.sort(key=lambda x: x[0])
        merged = [list(intervals[0])]
        for s, e in intervals[1:]:
            if s <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        return [tuple(m) for m in merged]

    base_merged = merge(base)
    cuts_merged = merge(cuts)

