            if c_end <= cur_start:
                i += 1
                continue
            # Overlap exists
            if c_start < cur_start:
                cur_start = c_end
            else:
                if c_end > cur_end:
                    cur_end = c_end
            i += 1
        if cur_start < cur_end:
            result.append((cur_start, cur_end))
