hjs-002.text:
I will implement `pLimit` by maintaining a pool of up to `n` concurrent workers, using an array to track active promises and a queue for pending jobs. Each incoming job is added to the queue, and when a worker slot becomes free the next job is started. Rejections are handled locally so they don’t block the queue or leave slots occupied.

ANSWER:
```javascript
function pLimit(n) {
  const queue = [];
  let activeCount = 0;

  const runNext = () => {
    if (activeCount >= n || queue.length === 0) return;
    const { fn, resolve, reject } = queue.shift();
    activeCount++;
    Promise.resolve(fn())
      .then(resolve)
      .catch(reject)
      .finally(() => {
        activeCount--;
        runNext();
      });
  };

  return (fn) => new Promise((resolve, reject) => {
    queue.push({ fn, resolve, reject });
    runNext();
  });
}

module.exports = pLimit;
```

