hjs-004.text:
I will implement the JSON Pointer functions by first handling the special empty pointer case, then decoding the tilde escapes, splitting the path, and processing each token. For `get`, I'll traverse the document while throwing when the pointer is invalid, and for `set`, I'll create missing objects and handle array appending with the `-` token.

ANSWER:
```javascript
function decode(token) {
  return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

function get(doc, pointer) {
  if (pointer === '') return doc;
  if (!pointer.startsWith('/')) throw new Error('Invalid pointer');
  const tokens = pointer.substring(1).split('/').map(decode);
  let current = doc;
  for (const token of tokens) {
    if (current == null) return undefined;
    current = current[token];
  }
  return current;
}

function set(doc, pointer, value) {
  if (pointer === '') return value;
  if (!pointer.startsWith('/')) throw new Error('Invalid pointer');
  const tokens = pointer.substring(1).split('/').map(decode);
  let current = doc;
  for (let i = 0; i < tokens.length - 1; i++) {
    const token = tokens[i];
    if (current[token] == null) {
      const next = tokens[i + 1];
      current[token] = isNaN(next) ? {} : [];
    }
    current = current[token];
  }
  const lastToken = tokens[tokens.length - 1];
  if (lastToken === '-') {
    if (Array.isArray(current)) current.push(value);
    else throw new Error('Cannot append to non-array');
  } else {
    current[lastToken] = value;
  }
  return doc;
}

module.exports = { get, set };
```

