I will implement a debounce function that supports leading and trailing options, along with cancel and flush methods. The function will handle the timing of calls based on the options, ensuring that the most recent invocation's `this` and arguments are used for the trailing call. Edge cases include handling multiple rapid calls and ensuring the correct behavior when both leading and trailing are enabled.

ANSWER: 
```javascript
function debounce(fn, wait, options = {}) {
  let timeoutId;
  let lastArgs;
  let lastThis;
  let lastCallTime;
  const { leading = false, trailing = true } = options;

  const invokeFunction = (time) => {
    const args = lastArgs;
    const thisArg = lastThis;
    lastArgs = lastThis = null;
    return fn.apply(thisArg, args);
  };

  const leadingEdge = (time) => {
    lastCallTime = time;
    timeoutId = setTimeout(timerExpired, wait);
    return leading ? invokeFunction(time) : undefined;
  };

  const remainingWait = (time) => {
    const timeSinceLastCall = time - lastCallTime;
    const timeWaiting = wait - timeSinceLastCall;
    return timeWaiting > 0 ? timeWaiting : 0;
  };

  const shouldInvoke = (time) => {
    const timeSinceLastCall = time - lastCallTime;
    return (
      lastCallTime === null ||
      timeSinceLastCall >= wait ||
      (timeSinceLastCall < 0 && leading)
    );
  };

  const timerExpired = () => {
    const time = Date.now();
    if (shouldInvoke(time)) {
      return trailing ? invokeFunction(time) : undefined;
    }
    timeoutId = setTimeout(timerExpired, remainingWait(time));
  };

  const cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    timeoutId = null;
    lastArgs = lastThis = null;
    lastCallTime = null;
  };

  const flush = () => {
    if (timeoutId !== null) {
      const time = Date.now();
      cancel();
      return invokeFunction(time);
    }
    return undefined;
  };

  const debounced = (...args) => {
    const time = Date.now();
    const isInvoking = shouldInvoke(time);
    lastArgs = args;
    lastThis = this;
    lastCallTime = time;
    if (isInvoking) {
      if (timeoutId === null) {
        return leadingEdge(time);
      }
      if (leading) {
        cancel();
        return leadingEdge(time);
      }
    } else if (timeoutId === null) {
      timeoutId = setTimeout(timerExpired, wait);
    }
    return undefined;
  };

  debounced.cancel = cancel;
  debounced.flush = flush;

  return debounced;
}

module.exports = debounce;
