hjs-006.text:
I will implement an `Emitter` class that maintains a map of event names to arrays of listener functions. The `on` method will push listeners onto the array and return an unsubscribe function that removes the listener. The `once` method will wrap the listener in a function that removes itself after being called once. The `off` method will remove a specific listener from the array. The `emit` method will iterate over a copy of the listener array, invoking each listener with the provided arguments, collecting any errors, and finally rethrowing the first error encountered. Listeners added or removed during an emit will not affect the current emit cycle, and throwing listeners will not prevent others from running.

ANSWER:
```javascript
class Emitter {
  constructor() {
    this.events = new Map();
  }

  on(event, fn) {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const listeners = this.events.get(event);
    listeners.push(fn);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapped = (...args) => {
      this.off(event, wrapped);
      fn(...args);
    };
    return this.on(event, wrapped);
  }

  off(event, fn) {
    if (!this.events.has(event)) return;
    const listeners = this.events.get(event);
    const index = listeners.indexOf(fn);
    if (index !== -1) listeners.splice(index, 1);
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return 0;
    const listeners = this.events.get(event);
    const copy = listeners.slice();
    let count = 0;
    let error = null;

    for (const fn of copy) {
      try {
        fn(...args);
        count++;
      } catch (e) {
        if (!error) error = e;
      }
    }

    if (error) throw error;
    return count;
  }
}

module.exports = Emitter;
```

