hjs-009.text:
I will create a recursive `observe` function that returns a Proxy for any plain object or array. The Proxy will intercept property assignments and deletions, building a path array from the root to the changed property. When a value is written, it compares the new value with the old one using SameValueZero semantics; if they differ, it calls `onChange` with the path, new value, and old value. For deletions, the reported new value is `undefined`. The handler also ensures that any nested object assigned later is wrapped in a new Proxy so future mutations are observed. Arrays are treated specially for `push` so that the index of the added element is reported as the path.

ANSWER:
```javascript
function observe(target, onChange, path = []) {
  const handler = {
    get(obj, prop, receiver) {
      const value = Reflect.get(obj, prop, receiver);
      if (typeof value === 'object' && value !== null) {
        return observe(value, onChange, [...path, prop]);
      }
      return value;
    },
    set(obj, prop, value) {
      const oldValue = obj[prop];
      if (Object.is(value, oldValue)) return true;
      obj[prop] = value;
      onChange([...path, prop], value, oldValue);
      return true;
    },
    deleteProperty(obj, prop) {
      const oldValue = obj[prop];
      delete obj[prop];
      onChange([...path, prop], undefined, oldValue);
      return true;
    }
  };

  if (Array.isArray(target)) {
    const arrayHandler = {
      ...handler,
      push(arr, ...items) {
        const start = arr.length;
        const result = Array.prototype.push.apply(arr, items);
        for (let i = start; i < arr.length; i++) {
          onChange([...path, i], arr[i], undefined);
        }
        return result;
      }
    };
    return new Proxy(target, arrayHandler);
  }

  return new Proxy(target, handler);
}

module.exports = { observe };
```

