hjs-010.text:
I will implement `chunkAsync` as an async generator that lazily pulls items from the source, keeping at most `size` items buffered ahead of consumption. The generator will handle both sync and async iterables by normalizing them to async iteration, and it will call the source’s `return()` method when the consumer stops early to clean up resources.

ANSWER: 
```javascript
async function* chunkAsync(source, size) {
  if (size <= 0) throw new Error('size must be positive');
  const iterator = source[Symbol.asyncIterator] 
    ? source[Symbol.asyncIterator]() 
    : {
        next: () => Promise.resolve({ value: source.next(), done: false }),
        return: () => Promise.resolve({ value: undefined, done: true })
      };
  let buffer = [];
  let done = false;

  const fill = async () => {
    if (done) return;
    while (buffer.length < size) {
      const { value, done: d } = await iterator.next();
      if (d) {
        done = true;
        break;
      }
      buffer.push(value);
    }
  };

  try {
    while (true) {
      if (buffer.length === 0) {
        await fill();
        if (buffer.length === 0) break;
      }
      const chunk = buffer.splice(0, size);
      yield chunk;
    }
  } finally {
    if (!done) {
      await iterator.return?.();
    }
  }
}

module.exports = { chunkAsync };
```

