hpy-030.text:
I'll implement a Spreadsheet class that handles cell values and formulas with dependency tracking. The approach involves:
1. Storing cell values and formulas separately
2. Maintaining a dependency graph to track which cells reference others
3. Using a topological sort to detect cycles when setting formulas
4. Caching computed values and invalidating dependent cells when values change
5. Implementing lazy evaluation with memoization for O(1) amortized get operations

Edge cases to consider:
- Circular references (e.g., A1 = B1, B1 = A1)
- Unset cells defaulting to 0
- Formula precedence (multiplication before addition/subtraction)
- Deep dependency chains (5000 levels as tested)

```python
class Spreadsheet:
    def __init__(self):
        self.values = {}
        self.formulas = {}
        self.dependencies = {}
        self.dependents = {}
        self.cache = {}

    def set(self, cell, value):
        # Check for cycles if value is a formula
        if isinstance(value, str) and value.startswith('='):
            # Parse formula to extract cell references
            refs = self._extract_cell_refs(value)
            # Check for cycles using DFS
            if self._has_cycle(cell, refs):
                raise ValueError("Circular reference detected")

        # Store the new value
        old_value = self.values.get(cell)
        self.values[cell] = value
        self.formulas.pop(cell, None)

        # Update dependencies
        if isinstance(value, str) and value.startswith('='):
            refs = self._extract_cell_refs(value)
            self.dependencies[cell] = refs
            for ref in refs:
                if ref not in self.dependents:
                    self.dependents[ref] = set()
                self.dependents[ref].add(cell)
        else:
            self.dependencies[cell] = []

        # Invalidate cache for this cell and all dependents
        self._invalidate_cache(cell)

    def get(self, cell):
        # Return cached value if available
        if cell in self.cache:
            return self.cache[cell]

        # If cell has a formula, evaluate it
        if cell in self.formulas:
            value = self._evaluate_formula(self.formulas[cell])
        elif cell in self.values:
            value = self.values[cell]
        else:
            value = 0

        # Cache the result
        self.cache[cell] = value
        return value

    def _extract_cell_refs(self, formula):
        # Simple regex to extract cell references (e.g., A1, B2)
        import re
        return re.findall(r'[A-Z]+\d+', formula)

    def _has_cycle(self, cell, refs):
        # DFS to detect cycles
        visited = set()
        rec_stack = set()

        def dfs(current):
            if current in rec_stack:
                return True
            if current in visited:
                return False

            visited.add(current)
            rec_stack.add(current)

            # Check dependencies of current cell
            if current in self.dependencies:
                for dep in self.dependencies[current]:
                    if dfs(dep):
                        return True

            rec_stack.remove(current)
            return False

        # Check if any dependency leads back to the cell
        for ref in refs:
            if ref == cell:
                return True
            if dfs(ref):
                return True

        return False

    def _evaluate_formula(self, formula):
        # Replace cell references with their values
        import re
        def replace_cell(match):
            cell = match.group(0)
            return str(self.get(cell))

        # Replace all cell references with their values
        expr = re.sub(r'[A-Z]+\d+', replace_cell, formula)

        # Evaluate the expression with proper precedence
        # Using eval is safe here since we control the input
        try:
            return eval(expr)
        except:
            return 0

    def _invalidate_cache(self, cell):
        # Remove cell from cache
        if cell in self.cache:
            del self.cache[cell]

        # Invalidate all dependents
        if cell in self.dependents:
            for dependent in self.dependents[cell]:
                self._invalidate_cache(dependent)
