hjs-014.text:
I will implement a Redux‑style store that captures the current state, queues actions, and notifies subscribers. The core challenge is handling nested dispatches and ensuring that the subscriber list is a snapshot taken before each notification, while also preventing reducers from dispatching. I'll use a flag to detect reducer‑initiated dispatches and a queue to process actions sequentially.

ANSWER: 
```javascript
function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let isDispatching = false;
  let isReducerDispatching = false;

  function getState() {
    return state;
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  function dispatch(action) {
    if (isDispatching) {
      throw new Error('Reducers may not dispatch actions.');
    }
    if (isReducerDispatching) {
      throw new Error('Dispatching from inside a reducer is not allowed.');
    }

    isDispatching = true;
    try {
      state = reducer(state, action);
    } finally {
      isDispatching = false;
    }

    const snapshot = listeners.slice();
    for (const listener of snapshot) {
      listener();
    }

    return action;
  }

  return { getState, dispatch, subscribe };
}

module.exports = createStore;
```

