      }
      if (isArray) {
        if (!Array.isArray(target[cur])) target[cur] = [];
        if (idx === -1) idx = target[cur].length;
        target = target[cur][idx];
      } else {
        if (name === '') {
          if (!Array.isArray(target[cur])) target[cur] = [];
          target = target[cur];
          isArray = true;
          idx = target.length;
        } else {
          if (!target.hasOwnProperty(name)) target[name] = {};
          target = target[name];
        }
      }
      cur = name;
    }
    if (isArray) {
      if (idx === -1) target.push(value);
      else target[idx] = value;
