I'll create a TypeScript module that implements a type-safe event bus with proper typing for different event payloads, including handling void events differently. The implementation will use generics to ensure type safety while maintaining runtime functionality.

ANSWER:
```typescript
export class Bus<E extends Record<string, unknown>> {
  private listeners: Map<keyof E, Array<{ fn: Function; once: boolean }>> = new Map();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.listeners.has(k)) {
      this.listeners.set(k, []);
    }
    const listeners = this.listeners.get(k)!;
    const wrappedFn = (payload: E[K]) => {
      if (listeners.some(l => l.fn === fn)) {
        fn(payload);
      }
    };
    listeners.push({ fn: wrappedFn, once: false });

    return () => {
      const index = listeners.findIndex(l => l.fn === wrappedFn);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K] | void): void {
    const listeners = this.listeners.get(k);
    if (!listeners) return;

    const type = typeof payload;
    const isVoid = type === 'undefined' || payload === undefined;

    if (isVoid) {
      listeners.forEach(({ fn, once }) => {
        fn();
        if (once) {
          const index = listeners.findIndex(l => l.fn === fn);
          if (index !== -1) listeners.splice(index, 1);
        }
      });
    } else {
      listeners.forEach(({ fn, once }) => {
        fn(payload);
        if (once) {
          const index = listeners.findIndex(l => l.fn === fn);
          if (index !== -1) listeners.splice(index, 1);
        }
      });
    }
  }
}
